    wire [OW-1:0] o_m = {m_s_done, m_seq_ntok, m_seq_nval, m_s_fault, m_core_fault, m_coll_busy, m_kv_write_flush, m_kvd_v, m_kvd_wbase, m_kvd_ts, m_kvd_ks, m_kvd_js, m_kvd_wcs, m_kvd_split, m_kvd_jsh, m_kvd_tiles, m_kvd_k, m_kvd_nout, m_kvd_kindk, m_kvd_pos, m_vm_re, m_vm_raddr, m_vm_we, m_vm_waddr, m_vm_wdata, m_c_valid, m_c_data, m_c_last, m_c_mode, m_c_tag, m_rom_fault, m_su_asrc, m_su_tok, m_po_me_go, m_po_me_i_nout, m_po_me_i_tiles, m_po_me_i_k, m_po_me_i_wsrc, m_po_me_i_wbase, m_po_me_i_ts, m_po_me_i_ks, m_po_me_i_js, m_po_me_i_xbase, m_po_me_i_xks, m_po_me_i_xjs, m_po_me_i_xcs, m_po_me_i_jsh, m_po_me_i_split, m_po_me_i_wcs, m_po_me_i_round, m_po_me_i_obase, m_po_me_i_ots, m_po_me_i_ojs, m_po_me_i_mmode, m_po_me_i_oen, m_po_me_i_amax, m_po_me_i_rmax, m_po_me_i_mbase, m_po_su_go, m_po_su_i_nout, m_po_su_i_nin, m_po_su_i_asrc, m_po_su_i_abase, m_po_su_i_aso, m_po_su_i_asi, m_po_su_i_bsrc, m_po_su_i_bbase, m_po_su_i_bso, m_po_su_i_bsi, m_po_su_i_csrc, m_po_su_i_cbase, m_po_su_i_cso, m_po_su_i_csi, m_po_su_i_ma, m_po_su_i_mb, m_po_su_i_ad, m_po_su_i_sfu, m_po_su_i_mc, m_po_su_i_md, m_po_su_i_dst, m_po_su_i_dbase, m_po_su_i_dso, m_po_su_i_dsi, m_po_su_i_red, m_po_su_i_redsq, m_po_su_i_rbase, m_po_su_i_rso, m_po_su_i_imm1, m_po_su_i_imm2};
    wire [OW-1:0] o_r = {r_s_done, r_seq_ntok, r_seq_nval, r_s_fault, r_core_fault, r_coll_busy, r_kv_write_flush, r_kvd_v, r_kvd_wbase, r_kvd_ts, r_kvd_ks, r_kvd_js, r_kvd_wcs, r_kvd_split, r_kvd_jsh, r_kvd_tiles, r_kvd_k, r_kvd_nout, r_kvd_kindk, r_kvd_pos, r_vm_re, r_vm_raddr, r_vm_we, r_vm_waddr, r_vm_wdata, r_c_valid, r_c_data, r_c_last, r_c_mode, r_c_tag, r_rom_fault, r_su_asrc, r_su_tok, r_po_me_go, r_po_me_i_nout, r_po_me_i_tiles, r_po_me_i_k, r_po_me_i_wsrc, r_po_me_i_wbase, r_po_me_i_ts, r_po_me_i_ks, r_po_me_i_js, r_po_me_i_xbase, r_po_me_i_xks, r_po_me_i_xjs, r_po_me_i_xcs, r_po_me_i_jsh, r_po_me_i_split, r_po_me_i_wcs, r_po_me_i_round, r_po_me_i_obase, r_po_me_i_ots, r_po_me_i_ojs, r_po_me_i_mmode, r_po_me_i_oen, r_po_me_i_amax, r_po_me_i_rmax, r_po_me_i_mbase, r_po_su_go, r_po_su_i_nout, r_po_su_i_nin, r_po_su_i_asrc, r_po_su_i_abase, r_po_su_i_aso, r_po_su_i_asi, r_po_su_i_bsrc, r_po_su_i_bbase, r_po_su_i_bso, r_po_su_i_bsi, r_po_su_i_csrc, r_po_su_i_cbase, r_po_su_i_cso, r_po_su_i_csi, r_po_su_i_ma, r_po_su_i_mb, r_po_su_i_ad, r_po_su_i_sfu, r_po_su_i_mc, r_po_su_i_md, r_po_su_i_dst, r_po_su_i_dbase, r_po_su_i_dso, r_po_su_i_dsi, r_po_su_i_red, r_po_su_i_redsq, r_po_su_i_rbase, r_po_su_i_rso, r_po_su_i_imm1, r_po_su_i_imm2};
    reg [OW-1:0] hist [0:L];
    integer i, k, rk, cyc, bad, first_bad, seed, starts;
    // cycle cap: config (1,035) + CYCLES + slack; a hang FAILs instead of running into the loop's 2 h limit
    initial begin #(CYCLES + 1100 + 1000); $display("FAIL qfd_constants_sequencer watchdog: no verdict by cycle %0d", CYCLES + 2100); $finish; end
    always @(posedge clk) begin for (i = L; i > 0; i = i - 1) hist[i] <= hist[i-1]; hist[0] <= o_r; end
    wire [OW-1:0] o_rd = hist[L-1];
    // the unstationed ICG enable leaves IS edges after the reference's (its inputs are IS late, no output station)
    wire me_en_rd; integer bad_en;
    ot_hdc_delay #(.W(1), .D(IS)) u_men (.clk(clk), .rst_n(1'b1), .d(r_me_clk_en), .q(me_en_rd));
    task rnd_inputs;
        begin
            for (rk = 0; rk < NW; rk = rk + 32) tp_token[rk +: 32] = $random(seed);
            for (rk = 0; rk < NW; rk = rk + 32) tp_pos[rk +: 32] = $random(seed);
            kv_write_drained = $random(seed);
            kv_ok = $random(seed);
            me_mem_ok = $random(seed);
            for (rk = 0; rk < 512; rk = rk + 32) vm_rq[rk +: 32] = $random(seed);
            c_ready = $random(seed);
            r_valid = $random(seed);
            for (rk = 0; rk < 512; rk = rk + 32) r_data[rk +: 32] = $random(seed);
            r_last = $random(seed);
            r_rank = $random(seed);
            r_err = $random(seed);
            pi_me_ready = $random(seed);
            pi_me_idle = $random(seed);
            pi_me_wrom_re = $random(seed);
            for (rk = 0; rk < AW; rk = rk + 32) pi_me_wrom_addr[rk +: 32] = $random(seed);
            for (rk = 0; rk < NW; rk = rk + 32) pi_me_am_idx[rk +: 32] = $random(seed);
            for (rk = 0; rk < 32; rk = rk + 32) pi_me_am_val[rk +: 32] = $random(seed);
            pi_me_am_any = $random(seed);
            pi_me_progress = $random(seed);
            pi_me_fault = $random(seed);
            pi_su_rt_active = $random(seed);
            pi_su_rt_inflight = $random(seed);
            pi_su_ready = $random(seed);
            pi_su_idle = $random(seed);
            pi_su_wrom_re = $random(seed);
            for (rk = 0; rk < AW; rk = rk + 32) pi_su_wrom_addr[rk +: 32] = $random(seed);
            for (rk = 0; rk < SW; rk = rk + 32) pi_su_kv_we[rk +: 32] = $random(seed);
            pi_su_progress = $random(seed);
            pi_su_progress_rows = $random(seed);
            pi_su_fault = $random(seed);
            pi_me_ready = ($random(seed) & 3) != 0; pi_su_ready = ($random(seed) & 3) != 0;
            kv_ok = ($random(seed) & 7) != 0; kv_write_drained = ($random(seed) & 7) != 0; me_mem_ok = ($random(seed) & 15) != 0;
        end
    endtask
    initial begin
        seed = SEED; bad = 0; first_bad = -1; starts = 0;
        h_start = 0; pw_v = 0; dw_v = 0; pw_addr = 0; dw_addr = 0; pw_data = 0; dw_data = 0; rnd_inputs;
        for (i = 0; i <= L; i = i + 1) hist[i] = 0;
        repeat (3) @(negedge clk); rst_n = 1;
        // program and descriptor images through the configuration ports (random words; unit field 0..2)
        for (k = 0; k < 1024; k = k + 1) begin @(negedge clk); pw_v = 1; pw_addr = k; pw_data = {$random(seed), $random(seed)}; rnd_inputs; end
        for (k = 0; k < 8; k = k + 1) begin @(negedge clk); pw_v = 0; dw_v = 1; dw_addr = k;
            dw_data = {$random(seed), 8'd0, 6'd0, 2'd0, $random(seed) & 32'h0000ff3c} | (k == 7 ? 64'd3 : 64'd0); rnd_inputs; end
        @(negedge clk); dw_v = 0;
        for (cyc = 0; cyc < CYCLES; cyc = cyc + 1) begin
            @(negedge clk);
            if (cyc > L + 2 && (o_m !== o_rd || m_me_clk_en !== me_en_rd)) begin bad = bad + 1; if (first_bad < 0) first_bad = cyc; end
            rnd_inputs;
            h_start = (cyc % 700) == 5; if (h_start) starts = starts + 1;
        end
        if (bad == 0 && starts > 3) $display("PASS qfd_constants_sequencer IS=%0d OS=%0d cycles=%0d starts=%0d outputs=%0d bits latency+%0d", IS, OS, CYCLES, starts, OW, L);
        else $display("FAIL qfd_constants_sequencer mismatching cycles=%0d first=%0d", bad, first_bad);
        $finish;
    end
    integer fm, fr;
    initial begin fm = $fopen("/tmp/sq_b/fqh_m.txt", "w"); fr = $fopen("/tmp/sq_b/fqh_r.txt", "w"); end
    always @(posedge clk) begin
        if (m_po_me_go) $fdisplay(fm, "ME %h %h %h %h %h %h %h", m_po_me_i_nout, m_po_me_i_tiles, m_po_me_i_k, m_po_me_i_wbase, m_po_me_i_xbase, m_po_me_i_obase, m_po_me_i_split);
        if (r_po_me_go) $fdisplay(fr, "ME %h %h %h %h %h %h %h", r_po_me_i_nout, r_po_me_i_tiles, r_po_me_i_k, r_po_me_i_wbase, r_po_me_i_xbase, r_po_me_i_obase, r_po_me_i_split);
        if (m_po_su_go) $fdisplay(fm, "SU %h %h %h %h %h %h", m_po_su_i_nout, m_po_su_i_nin, m_po_su_i_abase, m_po_su_i_bbase, m_po_su_i_dbase, m_po_su_i_imm1);
        if (r_po_su_go) $fdisplay(fr, "SU %h %h %h %h %h %h", r_po_su_i_nout, r_po_su_i_nin, r_po_su_i_abase, r_po_su_i_bbase, r_po_su_i_dbase, r_po_su_i_imm1);
        if (m_kvd_v) $fdisplay(fm, "KV %h %h %h", m_kvd_wbase, m_kvd_tiles, m_kvd_pos);
        if (r_kvd_v) $fdisplay(fr, "KV %h %h %h", r_kvd_wbase, r_kvd_tiles, r_kvd_pos);
        if (dut.u_ctrl.load) $fdisplay(fm, "LD %h", dut.u_ctrl.ir);
        if (ref_core.load) $fdisplay(fr, "LD %h", ref_core.ir);
        if (m_s_done) $fdisplay(fm, "DONE");
        if (r_s_done) $fdisplay(fr, "DONE");
    end
